Our workaround:

```csharp
public class TimeOnlyKeyedImmutableSortedDictionary<TValue> : JsonConverter
{
    public override bool CanConvert(Type objectType)
    {
        return objectType == typeof(IDictionary) &&
               objectType.GenericTypeArguments[0] == typeof(TimeOnly) &&
               objectType.GenericTypeArguments[1] == typeof(TValue);
    }

    public override object? ReadJson(JsonReader reader, Type objectType, object? existingValue,
        JsonSerializer serializer)
    {
        var returnValue = new Dictionary<TimeOnly, TValue>();

        if (reader.TokenType != JsonToken.StartObject)
        {
            return returnValue.ToImmutableSortedDictionary();
        }

        reader.Read();

        while (reader.TokenType != JsonToken.EndObject)
        {
            if (reader.TokenType == JsonToken.PropertyName)
            {
                var key = reader.Value?.ToString() ?? "";

                var timeKey = string.IsNullOrEmpty(key)
                    ? new TimeOnly(0, 0, 0)
                    : TimeOnly.Parse(key, CultureInfo.InvariantCulture);

                // Move to value
                reader.Read();
                var value = serializer.Deserialize<TValue>(reader);

                ArgumentNullException.ThrowIfNull(value, nameof(value));
                returnValue[timeKey] = value;
            }

            reader.Read(); // Move to next property or end object
        }

        return returnValue.ToImmutableSortedDictionary();
    }

    public override void WriteJson(JsonWriter writer, object? value, JsonSerializer serializer)
    {
        if (value is not ImmutableSortedDictionary<TimeOnly, TValue> currentValue)
        {
            return;
        }

        writer.WriteStartObject();

        foreach (var kvp in currentValue)
        {
            writer.WritePropertyName(kvp.Key.ToString("HH:mm:ss"));
            serializer.Serialize(writer, kvp.Value);
        }

        writer.WriteEndObject();
    }
}
```

