The strategy we are considering which appears hopeful, is to have a custom ISerializationBinder that rewrite the collection type to List<T> when it detects an unspeakable collection expression type (this happens only for serialization (BindToName), so Deserialization utlizes all the default logic and materializes into a List)

Something along the lines of:

```cs
public class CollectionExpressionSerializationBinder : ISerializationBinder
{
	private readonly ISerializationBinder _wrappedBinder;

	public CollectionExpressionSerializationBinder(
		ISerializationBinder wrappedBinder
	)
	{
		_wrappedBinder = wrappedBinder;
	}

	// Serialization
	public void BindToName(Type serializedType, out string? assemblyName, out string? typeName)
	{
		if (IsCollectionExpressionUnspeakableType(serializedType, out Type? elementType))
		{
			serializedType = typeof(List<>).MakeGenericType(elementType);
		}

		_wrappedBinder.BindToName(serializedType, out assemblyName, out typeName);
	}

	// Deserialization
	public Type BindToType(string? assemblyName, string typeName)
	{
		return _wrappedBinder.BindToType(assemblyName, typeName);
	}

	private static bool IsCollectionExpressionUnspeakableType(
		Type type,
		[NotNullWhen(returnValue: true)]
		out Type? elementType
	)
	{
		// Detection logic
	}
}
```

I used the code provided by @WGroenestein  and implemented IsCollectionExpressionUnspeakableType like this: 

```
private static bool IsCollectionExpressionUnspeakableType(Type type, out Type? elementType)
{
    elementType = null;

    if (!type.IsGenericType)
        return false;

    // Check if type is compiler-generated
    var isCompilerGenerated = type.GetCustomAttributes(typeof(CompilerGeneratedAttribute), false).Length != 0;
    if (!isCompilerGenerated)
        return false;

    // Check if implements IEnumerable<T>
    var ienumerableInterface = type
        .GetInterfaces()
        .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IEnumerable<>));
    if (ienumerableInterface == null)
        return false;

    elementType = ienumerableInterface.GetGenericArguments()[0];
    return true;
}
```

