The default JSON serializer for ASP.NET Core 3.0 is changed to System.Text.Json. This doesn't fully compatible with NewtonSoft.Json de-serialized object return by the controller. So we need to add NewtonSoft default serializer settings.

I've put together a little implementation for you... This is not very optimised and there may be a few differences from how you want it to work (although you should be able to tweak it from there).

While this should handle any generic type of `IDictionary<string,?>`, I haven't done anything around handling mixed dictionary with additional properties type objects, nor supporting things like `TypeNameHandling` and so on. I'm sure it could be fleshed out if required.

The code uses reflection to bind the methods, and that code should probably be made more thread-safe (although I think it should work pretty well as-is). There might be better ways to implement that using code expressions, but for a proof of concept I think it is good enough.

This is designed for net8.0, but if you strip the nullability stuff out, it should be fine on net4x too. You might need to tweak the code format as it uses collection initialisers in some places...

HTH

```cs
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;
using System.Collections;
using System.Diagnostics.CodeAnalysis;
using System.Reflection;

public static class Program
{
    public static void Main()
    {
        var d = new Dictionary<string, int>
        {
            ["a"] = 1,
            ["c"] = 2,
            ["b"] = 3,
        };
        var d2 = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["x"] = "World",
            ["Y"] = "Hello",
        };
        var a = new
        {
            values = d,
            Stuff = "this",
            greeting = d2
        };
        var s = new JsonSerializerSettings
        {
            ContractResolver = new SortedPropertyNamesContractResolver(StringComparer.Ordinal),
            Converters = [new SortedDictionaryConverter(StringComparer.Ordinal)]    // N.B. The sort order here is only used if the dictionary is an IDictionary and not a Dictionary with a sort order set
        };
        Console.WriteLine(JsonConvert.SerializeObject(a));    // yields {"values":{"a":1,"c":2,"b":3},"Stuff":"this","greeting":{"x":"World","Y":"Hello"}}
        Console.WriteLine(JsonConvert.SerializeObject(a, s)); // yields {"Stuff":"this","greeting":{"x":"World","Y":"Hello"},"values":{"a":1,"b":3,"c":2}}

        Console.WriteLine(JsonConvert.SerializeObject(d2, s)); // yields {"x":"World","Y":"Hello"}
        Console.WriteLine(JsonConvert.SerializeObject(new CustomDictionary<string>(d2), s)); // yields {"Y":"Hello","x":"World"}
        // CustomDictionary<string> is an IDictionary<string,string> but has no access to the key sort order, so we use the default passed to SortedDictionaryConverter
    
        var d3 = JsonConvert.DeserializeObject<Dictionary<string, string>>(JsonConvert.SerializeObject(d2,s), s); // Check we can deserialize
        foreach (var k in d3.Keys)
        {
            Console.WriteLine($"{k}={d3[k]}");
        }
    }
}

public class SortedDictionaryConverter : JsonConverter
{
    private readonly IComparer<string> comparer;

    public SortedDictionaryConverter() : this(StringComparer.Ordinal) { }
    public SortedDictionaryConverter(IComparer<string> comparer) => this.comparer = comparer ?? throw new ArgumentNullException(nameof(comparer));

    private static readonly Type idic = typeof(IDictionary<,>);

    public override bool CanConvert(Type objectType)
    {
        return objectType.GetInterfaces().Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == idic &&
            i.GetGenericArguments().First() == typeof(string));
    }

    public override object ReadJson(JsonReader reader, Type objectType, object? existingValue, JsonSerializer serializer) => throw new NotImplementedException();

    public override bool CanWrite => true;
    public override bool CanRead => false;

    private static readonly Dictionary<Type, Action<JsonWriter, object, JsonSerializer, IComparer<string>>> writeJsonMethods = [];
    private static readonly MethodInfo wji = typeof(SortedDictionaryConverter).GetMethod(nameof(WriteJsonInternal), BindingFlags.Static | BindingFlags.NonPublic)!;

    public override void WriteJson(JsonWriter writer, object? value, JsonSerializer serializer)
    {
        if (value is null) { writer.WriteNull(); return; }
        if (value is IDictionary d && d.Count == 0) { writer.WriteStartObject(); writer.WriteEndObject(); return; }

        var iface = value.GetType().GetInterfaces().First(i => i.GetGenericTypeDefinition() == idic &&
            i.GetGenericArguments().First() == typeof(string));

        var dtype = iface.GetGenericArguments()[1]; // iface is IDictionary<string,{dtype}>

        if (!writeJsonMethods.TryGetValue(dtype, out var method))
        {
            var mi = wji.MakeGenericMethod(dtype) ?? throw new NotImplementedException();
            // 
            method = wji.MakeGenericMethod(dtype).CreateDelegate<Action<JsonWriter, object, JsonSerializer, IComparer<string>>>(null);
            writeJsonMethods[dtype] = method;
        }
        method(writer, value, serializer, comparer);
    }

    private static void WriteJsonInternal<T>(JsonWriter writer, object value, JsonSerializer serializer, IComparer<string> defaultComparer)
    {
        if (value is not IDictionary<string,T> idict) throw new ArgumentOutOfRangeException(nameof(value));

        var dict = idict as Dictionary<string, T>;
        var comparer = dict?.Comparer as IComparer<string> ?? defaultComparer; // Try and use the dictionary's comparer but fallback if unavailable

        writer.WriteStartObject();

        foreach (var key in idict.Keys.OrderBy(k => k, comparer))
        {
            writer.WritePropertyName(key);
            serializer.Serialize(writer, idict[key]);
        }

        writer.WriteEndObject();
    }
}

public class SortedPropertyNamesContractResolver : DefaultContractResolver
{
    private readonly IComparer<string> comparer;

    public SortedPropertyNamesContractResolver() : this(StringComparer.Ordinal) { }
    public SortedPropertyNamesContractResolver(IComparer<string> comparer) => this.comparer = comparer ?? throw new ArgumentNullException(nameof(comparer));

    protected override IList<JsonProperty> CreateProperties(Type type, MemberSerialization memberSerialization) => 
        base.CreateProperties(type, memberSerialization).OrderBy(property => property.PropertyName!, comparer).ToList();
    // This does not override explicitly ordered properties
}

public class CustomDictionary<T> : IDictionary<string,T>
{
    private readonly IDictionary<string, T> source;

    public CustomDictionary(IDictionary<string, T> source) => this.source = source;

    public T this[string key] { get => source[key]; set => source[key] = value; }

    public ICollection<string> Keys => source.Keys;

    public ICollection<T> Values => source.Values;

    public int Count => source.Count;

    public bool IsReadOnly => source.IsReadOnly;

    public void Add(string key, T value) => source.Add(key, value);

    public void Add(KeyValuePair<string, T> item) => source.Add(item);

    public void Clear() => source.Clear();

    public bool Contains(KeyValuePair<string, T> item) => source.Contains(item);

    public bool ContainsKey(string key) => source.ContainsKey(key);

    public void CopyTo(KeyValuePair<string, T>[] array, int arrayIndex) => source.CopyTo(array, arrayIndex);

    public IEnumerator<KeyValuePair<string, T>> GetEnumerator() => source.GetEnumerator();

    public bool Remove(string key) => source.Remove(key);

    public bool Remove(KeyValuePair<string, T> item) => source.Remove(item);

    public bool TryGetValue(string key, [MaybeNullWhen(false)] out T value) => source.TryGetValue(key, out value);

    IEnumerator IEnumerable.GetEnumerator() => ((IEnumerable)source).GetEnumerator();
}
```

